scwin.gridVeiw1_onbeforetoggleclick = function(rowIndex) {
	console.log(`onbeforetoggleclick!! 클릭된 row: ${rowIndex}`);
	window.check_val = `onbeforetoggleclick!! 클릭된 row: ${rowIndex}`;		
	return false; //toggle 취소
	//return true; //toggle 됨
}

scwin.checkVal = function() {
	return window.check_val == 'onbeforetoggleclick!! 클릭된 row: 0';
}
scwin.unitTest = function() {
	//init
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "1000");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_0_0').querySelector('span').click()");
	WebSquare.wUnit.addCommand("pause", "500");		
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
	WebSquare.wUnit.addCommand("pause", "500");
	//Run  and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}
scwin.unitTest()
